const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// =====================================================================
//  ROUTEUR : transforme un message / clic Telegram en action
//  route = db | letter | ai | import | cv | collect | report | text
// =====================================================================
const STATUS_FR = {
  nouveau: 'new', selection: 'shortlisted', sélection: 'shortlisted', postule: 'applied', postulé: 'applied',
  entretien: 'interview', offre: 'offer', refus: 'rejected', ignore: 'ignored', ignoré: 'ignored',
  'sans-reponse': 'ghosted', 'sans-réponse': 'ghosted',
};

const SQL = {
  offres: `SELECT id, title, company, location, score, status FROM jobs
           WHERE score IS NOT NULL AND status IN ('new','shortlisted') AND collected_at > now() - interval '14 days'
           ORDER BY score DESC, collected_at DESC LIMIT 10`,
  offre: `SELECT j.*, a.applied_at, a.followup_count,
            (SELECT count(*) FROM documents d WHERE d.job_id = j.id AND d.kind = 'cover_letter')::int AS letters
          FROM jobs j LEFT JOIN applications a ON a.job_id = j.id WHERE j.id = $1::int`,
  chercher: `SELECT id, title, company, score, status FROM jobs, websearch_to_tsquery('french', $1) q
             WHERE search_vector @@ q ORDER BY ts_rank(search_vector, q) DESC, score DESC NULLS LAST LIMIT 10`,
  apply: `WITH j AS (UPDATE jobs SET status = 'applied' WHERE id = $1::int RETURNING id, title, company),
               a AS (INSERT INTO applications (job_id, applied_at, next_followup_at)
                     SELECT id, now(), now() + interval '7 days' FROM j
                     ON CONFLICT (job_id) DO UPDATE SET applied_at = now(), next_followup_at = now() + interval '7 days'
                     RETURNING id, next_followup_at)
          SELECT j.*, a.id AS application_id, to_char(a.next_followup_at, 'DD/MM') AS followup_date FROM j, a`,
  status: `WITH j AS (UPDATE jobs SET status = $2 WHERE id = $1::int RETURNING id, title, company, status),
               a AS (INSERT INTO applications (job_id) SELECT id FROM j WHERE status IN ('interview','offer','rejected')
                     ON CONFLICT (job_id) DO NOTHING RETURNING id)
          SELECT j.* FROM j`,
  followup: `UPDATE applications a SET followup_count = a.followup_count + 1, last_followup_at = now(),
               next_followup_at = now() + interval '7 days'
             FROM jobs j WHERE a.id = $1::int AND j.id = a.job_id
             RETURNING a.id, a.followup_count, j.title, to_char(a.next_followup_at, 'DD/MM') AS next_date`,
  snooze: `UPDATE applications a SET next_followup_at = now() + interval '3 days'
           FROM jobs j WHERE a.id = $1::int AND j.id = a.job_id
           RETURNING a.id, j.title, to_char(a.next_followup_at, 'DD/MM') AS next_date`,
  candidatures: `SELECT j.id, j.title, j.company, j.status, to_char(a.applied_at, 'DD/MM') AS applied,
                   (current_date - a.applied_at::date) AS days, a.followup_count
                 FROM jobs j JOIN applications a ON a.job_id = j.id
                 WHERE j.status IN ('applied','interview','offer')
                 ORDER BY CASE j.status WHEN 'offer' THEN 0 WHEN 'interview' THEN 1 ELSE 2 END, a.applied_at DESC
                 LIMIT 30`,
  stats: `SELECT (SELECT count(*) FROM jobs)::int AS total,
                 (SELECT count(*) FROM jobs WHERE scored_at IS NOT NULL)::int AS scored,
                 (SELECT round(avg(score)) FROM jobs)::int AS avg_score,
                 (SELECT count(*) FROM jobs WHERE collected_at > now() - interval '7 days')::int AS week_collected,
                 (SELECT count(*) FROM applications)::int AS applications,
                 (SELECT count(*) FROM status_history WHERE to_status = 'applied' AND changed_at > now() - interval '7 days')::int AS week_applied,
                 (SELECT count(*) FROM jobs WHERE status = 'interview')::int AS interviews,
                 (SELECT count(*) FROM jobs WHERE status = 'offer')::int AS offers,
                 (SELECT count(*) FROM jobs WHERE status = 'rejected')::int AS rejected,
                 (SELECT count(*) FROM jobs WHERE status = 'ghosted')::int AS ghosted,
                 (SELECT count(*) FROM jobs j JOIN applications a ON a.job_id = j.id WHERE j.status IN ('interview','offer','rejected'))::int AS answered,
                 (SELECT coalesce(json_agg(t), '[]') FROM (SELECT skill, occurrences FROM v_missing_skills LIMIT 5) t) AS missing_skills`,
  recherches: `SELECT id, label, keywords, department, contract_type, active, last_count,
                 to_char(last_run_at, 'DD/MM HH24:MI') AS last_run FROM searches ORDER BY active DESC, id`,
  recherche_ajouter: `INSERT INTO searches (label, keywords, department, contract_type)
                      VALUES ($1, $1, NULLIF($2, ''), NULLIF(upper($3), '')) RETURNING *`,
  recherche_retirer: `UPDATE searches SET active = false WHERE id = $1::int RETURNING id, label`,
  flux: `SELECT id, name, url, active, last_count, error_count, last_error FROM feeds ORDER BY active DESC, id`,
  flux_ajouter: `INSERT INTO feeds (name, url) VALUES (COALESCE(NULLIF($2, ''), $1), $1)
                 ON CONFLICT (url) DO UPDATE SET active = true, error_count = 0 RETURNING *`,
  flux_retirer: `UPDATE feeds SET active = false WHERE id = $1::int RETURNING id, name`,
  profil: `SELECT * FROM profile WHERE id = 1`,
  seuil: `UPDATE profile SET alert_threshold = $1::int, updated_at = now() WHERE id = 1 RETURNING alert_threshold`,
  reanalyser: `WITH u AS (UPDATE jobs SET scored_at = NULL, score_attempts = 0, scoring_started_at = NULL
                 WHERE status IN ('new','shortlisted') AND collected_at > now() - interval '14 days' RETURNING 1)
               SELECT count(*)::int AS n FROM u`,
};

