  '/seuil 75 · score minimum pour être alerté',
  '/reanalyser · recalculer les scores récents',
  '/recherches · /recherche_ajouter <i>mots | dépt | contrat</i> · /recherche_retirer 3',
  '/flux · /flux_ajouter <i>url nom</i> · /flux_retirer 2',
  '',
  '💬 Pose-moi aussi n\'importe quelle question sur ta recherche : je réponds en coach carrière.',
].join('\n');

const text = (t) => ({ route: 'text', text: t });
const db = (cmd, params = []) => ({ route: 'db', cmd, sql: SQL[cmd], params });
const needId = (id, usage) => (Number.isInteger(id) && id > 0 ? null : text(`Il me manque le numéro de l'offre. Exemple : <code>${usage}</code>`));

function routeCallback(data) {
  const [action, raw] = String(data || '').split(':');
  const id = parseInt(raw, 10);
  switch (action) {
    case 'apply': return db('apply', [id]);
    case 'skip': return db('status', [id, 'ignored']);
    case 'interview': return db('status', [id, 'interview']);
    case 'rejected': return db('status', [id, 'rejected']);
    case 'followup': return db('followup', [id]);
    case 'snooze': return db('snooze', [id]);
    case 'letter': return { route: 'letter', job_id: id, text: `✍️ Je rédige ta lettre pour l'offre #${id}… (≈ 20 s)` };
    case 'prep': return { route: 'ai', ai: 'prep', job_id: id, text: '' };
    default: return text('Action inconnue 🤔');
  }
}

function routeCommand(name, id, arg) {
  switch (name) {
    case 'start':
    case 'aide':
    case 'help': return text(HELP);
    case 'offres': return db('offres');
    case 'offre': return needId(id, '/offre_12') ?? db('offre', [id]);
    case 'chercher':
    case 'cherche': return arg ? db('chercher', [arg]) : text('Que veux-tu chercher ? Exemple : <code>/chercher react télétravail</code>');
    case 'lettre': return needId(id, '/lettre_12') ?? { route: 'letter', job_id: id, text: `✍️ Je rédige ta lettre pour l'offre #${id}… (≈ 20 s)` };
    case 'postuler': return needId(id, '/postuler_12') ?? db('apply', [id]);
    case 'entretien': return needId(id, '/entretien_12') ?? { route: 'ai', ai: 'prep', job_id: id };
    case 'statut': {
      const word = (arg || '').split(/\s+/).filter(Boolean).pop()?.toLowerCase();
      const status = STATUS_FR[word];
      if (!Number.isInteger(id) || !status) return text('Exemple : <code>/statut 12 entretien</code> (entretien, offre, refus, ignore, postulé)');
      return status === 'applied' ? db('apply', [id]) : db('status', [id, status]);
    }
    case 'candidatures': return db('candidatures');
    case 'stats': return db('stats');
    case 'recherches': return db('recherches');
    case 'recherche_ajouter': {
      const [kw, dept = '', contract = ''] = (arg || '').split('|').map((s) => s.trim());
      if (!kw) return text('Exemple : <code>/recherche_ajouter développeur react | 69 | CDI</code>');
      return db('recherche_ajouter', [kw, dept, contract]);
    }
    case 'recherche_retirer': return needId(id, '/recherche_retirer 3') ?? db('recherche_retirer', [id]);
    case 'flux': return db('flux');
    case 'flux_ajouter': {
      const [url, ...rest] = (arg || '').split(/\s+/);
      if (!/^https?:\/\//i.test(url || '')) return text('Exemple : <code>/flux_ajouter https://site.com/jobs.rss Mon flux</code>');
      return db('flux_ajouter', [url, rest.join(' ')]);
    }
    case 'flux_retirer': return needId(id, '/flux_retirer 2') ?? db('flux_retirer', [id]);
    case 'profil': return db('profil');
    case 'seuil': {
      const n = parseInt(arg, 10);
      if (!(n >= 0 && n <= 100)) return text('Exemple : <code>/seuil 75</code> (entre 0 et 100)');
      return db('seuil', [n]);
    }
    case 'reanalyser': return db('reanalyser');
    case 'collecter': return { route: 'collect', text: '📥 Collecte lancée ! Les nouvelles pépites arriveront ici dans quelques minutes.' };
    case 'rapport': return { route: 'report', text: '📊 Je prépare ton rapport…' };
    case 'dashboard': {
      const base = String($env.N8N_WEBHOOK_URL || 'http://localhost:5678/').replace(/\/?$/, '/');
      return text(`📈 Ton tableau de bord :\n${base}webhook/jobhunter?token=${encodeURIComponent($env.DASHBOARD_TOKEN || '')}`);
    }
    default: return text(`Commande inconnue : /${esc(name)}\n\n${HELP}`);
  }
}

const out = [];
for (const item of $input.all()) {
  const u = item.json;
  const cb = u.callback_query;
  const msg = cb ? cb.message : u.message;
  const base = { chat_id: msg?.chat?.id, is_callback: !!cb, callback_id: cb?.id ?? null, job_id: null };
  let r;

  if (cb) {
    r = routeCallback(cb.data);
  } else if (msg?.document) {
    r = msg.document.mime_type === 'application/pdf' && item.binary?.data
      ? { route: 'cv', text: '📄 CV reçu, je l\'analyse…' }
      : text('📄 Envoie ton CV au format <b>PDF</b> pour mettre à jour ton profil.');
  } else {
    const t = (msg?.text || '').trim();
    const cmd = t.match(/^\/([a-zà-ÿ]+(?:_[a-zà-ÿ]+)*)(?:_(\d+))?(?:@\w+)?(?:\s+([\s\S]+))?$/i);
    const url = t.match(/https?:\/\/[^\s<>"]+/i)?.[0];
    if (cmd) {
      const arg = (cmd[3] || '').trim();
      const id = cmd[2] ? parseInt(cmd[2], 10) : parseInt(arg, 10);
      r = routeCommand(cmd[1].toLowerCase(), Number.isNaN(id) ? null : id, arg);
    } else if (url) {
      r = { route: 'import', url, text: '' };
    } else if (t.length >= 400 && !t.trim().endsWith("?")) {
      // Long texte collé : c'est probablement une offre copiée depuis un site
      r = { route: 'import_text', url: null, pasted: t.slice(0, 15000), text: '' };
    } else if (t) {
      r = { route: 'ai', ai: 'coach', question: t.slice(0, 2000) };
    } else {
      r = text('Je ne sais pas encore traiter ce type de message 🙂 Tape /aide.');
    }
  }
  out.push({ json: { ...base, ...r }, ...(item.binary ? { binary: item.binary } : {}) });
}
return out;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const scoreEmoji = (s) => s >= 85 ? '🔥' : s >= 70 ? '✅' : s >= 50 ? '🟡' : '⚪';
const STATUS_LABEL = { new: '🆕 Nouvelle', shortlisted: '⭐ Sélectionnée', applied: '📨 Postulé', interview: '🎤 Entretien', offer: '🎉 Offre reçue', rejected: '❌ Refus', ignored: '🙈 Ignorée', ghosted: '👻 Sans réponse' };
// Telegram limite un message à 4096 caractères : on coupe proprement à la fin d'une ligne
const fit = (text, max = 3900) => {
  if (text.length <= max) return text;
  const cut = text.lastIndexOf('\n', max);
  return text.slice(0, cut > 0 ? cut : max) + '\n…';
};

// Met en forme le résultat SQL selon la commande
const ctx = $('Routeur').first().json;
// (PostgreSQL renvoie { success: true } quand la requête ne retourne aucune ligne)
const rows = $input.all().map((i) => i.json).filter((r) => Object.keys(r).length && !(r.success === true && Object.keys(r).length === 1));
const r0 = rows[0];
const out = { chat_id: ctx.chat_id, job_id: null, url: null, with_actions: false };
const notFound = '🤷 Introuvable. Vérifie le numéro avec /offres ou /candidatures.';
const list = (a) => (Array.isArray(a) && a.length ? a.join(', ') : '—');
let t;

switch (ctx.cmd) {
  case 'offres':
    t = rows.length
      ? ['🎯 <b>Tes meilleures offres du moment</b>', '', ...rows.map((j) =>
          `${scoreEmoji(j.score)} <b>${j.score}</b> · ${esc(j.title)}\n      🏢 ${esc(j.company || '—')} · 📍 ${esc(j.location || '—')}\n      👉 /offre_${j.id}`)].join('\n')
      : '📭 Aucune offre analysée pour l\'instant. Lance /collecter ou ajoute des recherches avec /recherche_ajouter.';
    break;

  case 'offre':
    if (!r0) { t = notFound; break; }
    out.job_id = r0.id; out.url = r0.url || 'https://francetravail.fr'; out.with_actions = true;
    t = [
      r0.score != null ? `${scoreEmoji(r0.score)} <b>${r0.score}/100 · match ${esc(r0.verdict)}</b>` : '⏳ <b>Analyse IA en attente</b>',
      `<b>${esc(r0.title)}</b>`,
      `🏢 ${esc(r0.company || '—')} · 📍 ${esc(r0.location || '—')}`,
      `📄 ${esc(r0.contract_type || '—')} · 🏠 ${esc(r0.remote || '—')} · 🎓 ${esc(r0.seniority || '—')}`,
      `💶 ${esc(r0.salary || (r0.estimated_salary ? r0.estimated_salary + ' (estimé)' : '—'))}`,
      `📌 Statut : ${STATUS_LABEL[r0.status] || r0.status}${r0.applied_at ? ' · postulé le ' + new Date(r0.applied_at).toLocaleDateString('fr-FR') : ''}${r0.letters ? ' · ✍️ ' + r0.letters + ' lettre(s)' : ''}`,
      ...(r0.summary ? ['', `📝 ${esc(r0.summary)}`] : []),
      ...(r0.strengths?.length ? ['', '<b>✅ Points forts</b>', ...r0.strengths.map((s) => `• ${esc(s)}`)] : []),
      ...(r0.gaps?.length ? ['', '<b>⚠️ Écarts</b>', ...r0.gaps.map((s) => `• ${esc(s)}`)] : []),
      ...(r0.key_skills?.length ? ['', `🛠️ <b>Compétences clés :</b> ${esc(list(r0.key_skills))}`] : []),
      ...(r0.missing_skills?.length ? [`🧩 <b>À renforcer :</b> ${esc(list(r0.missing_skills))}`] : []),
      ...(r0.red_flags?.length ? ['', '<b>🚩 Signaux d\'alerte</b>', ...r0.red_flags.map((s) => `• ${esc(s)}`)] : []),
      '', '<b>Extrait de l\'offre</b>', esc((r0.description || '').slice(0, 700)) + ((r0.description || '').length > 700 ? '…' : ''),
    ].join('\n');
    break;

  case 'chercher':
    t = rows.length
      ? [`🔎 <b>${rows.length} résultat(s)</b>`, '', ...rows.map((j) =>
          `${j.score != null ? scoreEmoji(j.score) + ' ' + j.score : '⏳'} · ${esc(j.title)} · ${esc(j.company || '—')} ${STATUS_LABEL[j.status]?.split(' ')[0] || ''}\n      👉 /offre_${j.id}`)].join('\n')
      : '🔎 Aucun résultat. Essaie d\'autres mots-clés.';
    break;

  case 'apply':
    t = r0
      ? `📨 <b>Candidature enregistrée !</b>\n${esc(r0.title)}${r0.company ? ' · ' + esc(r0.company) : ''}\n\n⏰ Je te proposerai une relance le <b>${r0.followup_date}</b> si tu n'as pas de nouvelles.\n🎤 Prépare-toi dès maintenant : /entretien_${r0.id}`
      : notFound;
    break;

  case 'status':
    if (!r0) { t = notFound; break; }
    t = {
      interview: `🎤 <b>Bravo pour l'entretien !</b> (${esc(r0.title)})\nJe te prépare les questions probables : /entretien_${r0.id}`,
      offer: `🎉🎉 <b>Félicitations pour l'offre !</b> (${esc(r0.title)})\nTu l'as bien mérité.`,
      rejected: `💪 Refus noté pour « ${esc(r0.title)} ». Chaque refus te rapproche du bon poste. Tes prochaines pistes : /offres`,
      ignored: `🙈 Offre « ${esc(r0.title)} » ignorée. Je ne te la proposerai plus.`,
    }[r0.status] ?? `📌 Statut mis à jour : ${STATUS_LABEL[r0.status]} · ${esc(r0.title)}`;
    break;

  case 'followup':
    t = r0 ? `✅ Relance n°${r0.followup_count} notée pour « ${esc(r0.title)} ». Prochain point le ${r0.next_date}.` : notFound;
    break;

  case 'snooze':
    t = r0 ? `⏳ OK, je te reparle de « ${esc(r0.title)} » le ${r0.next_date}.` : notFound;
    break;

  case 'candidatures': {
    if (!rows.length) { t = '📭 Aucune candidature en cours. Marque une offre avec ✅ « J\'ai postulé ».'; break; }
    const groups = ['offer', 'interview', 'applied'];
    t = ['📋 <b>Ton pipeline de candidatures</b>'];
    for (const g of groups) {
      const gr = rows.filter((r) => r.status === g);
      if (!gr.length) continue;
      t.push('', `<b>${STATUS_LABEL[g]} (${gr.length})</b>`);
      t.push(...gr.map((r) => `• ${esc(r.title)} · ${esc(r.company || '—')} · J+${r.days}${r.followup_count ? ' · ' + r.followup_count + ' relance(s)' : ''} → /offre_${r.id}`));
    }
    t = t.join('\n');
    break;
  }

  case 'stats': {
    const s = r0;
    const rate = s.applications ? Math.round((s.answered / s.applications) * 100) : 0;
    t = [
      '📊 <b>Tes chiffres</b>',
      '',
      `📥 ${s.total} offres collectées (${s.week_collected} cette semaine)`,
      `🤖 ${s.scored} analysées · score moyen ${s.avg_score ?? '—'}`,
      `📨 ${s.applications} candidatures (${s.week_applied} cette semaine)`,
      `🎤 ${s.interviews} entretiens · 🎉 ${s.offers} offres`,
      `❌ ${s.rejected} refus · 👻 ${s.ghosted} sans réponse`,
      `📈 Taux de réponse : <b>${rate}%</b>`,
      ...(s.missing_skills?.length ? ['', '🧩 <b>Compétences à renforcer</b> : ' + s.missing_skills.map((m) => `${esc(m.skill)} (${m.occurrences})`).join(', ')] : []),
    ].join('\n');
    break;
  }

  case 'recherches':
    t = ['🔍 <b>Tes recherches France Travail</b>', '', ...rows.map((s) =>
      `${s.active ? '🟢' : '⚪'} <b>#${s.id}</b> ${esc(s.keywords)}${s.department ? ' · dépt ' + esc(s.department) : ''}${s.contract_type ? ' · ' + esc(s.contract_type) : ''}${s.last_run ? `\n      dernière collecte ${s.last_run} · ${s.last_count ?? 0} offres` : ''}`),
      '', 'Ajouter : <code>/recherche_ajouter mots | dépt | contrat</code>'].join('\n');
    break;

  case 'recherche_ajouter':
    t = r0 ? `✅ Recherche #${r0.id} ajoutée : <b>${esc(r0.keywords)}</b>. Lance /collecter pour la tester tout de suite.` : '⚠️ Impossible d\'ajouter la recherche.';
    break;

  case 'recherche_retirer':
  case 'flux_retirer':
    t = r0 ? `🗑️ « ${esc(r0.label || r0.name)} » désactivé(e).` : notFound;
    break;

  case 'flux':
    t = ['📡 <b>Tes flux RSS</b>', '', ...rows.map((f) =>
      `${f.active ? (f.error_count ? '🟠' : '🟢') : '⚪'} <b>#${f.id}</b> ${esc(f.name)} · ${f.last_count ?? 0} offres${f.error_count ? `\n      ⚠️ ${f.error_count} erreur(s) : ${esc((f.last_error || '').slice(0, 80))}` : ''}`)].join('\n');
    break;

  case 'flux_ajouter':
    t = r0 ? `✅ Flux #${r0.id} « ${esc(r0.name)} » ajouté.` : '⚠️ Impossible d\'ajouter le flux.';
    break;

  case 'profil': {
    const p = r0 || {};
    t = [
      '👤 <b>Ton profil</b>',
      '',
      `<b>${esc(p.full_name || '—')}</b> · ${esc(p.headline || '')}`,
      `🎯 Postes : ${esc(list(p.target_roles))}`,
      `🛠️ Compétences : ${esc(list(p.skills))}`,
      `⏳ Expérience : ${p.years_experience ?? '—'} an(s)`,
      `📍 Lieux : ${esc(list(p.locations))} · 🏠 ${esc(p.remote_preference)}`,
      `📄 Contrats : ${esc(list(p.contract_types))}`,
      `🗣️ Langues : ${esc(list(p.languages))}`,
      `🔔 Seuil d'alerte : ${p.alert_threshold}/100`,
      `📎 CV : ${p.cv_text ? '✅ chargé (' + p.cv_text.length + ' caractères)' : '❌ non chargé · envoie-le en PDF ici'}`,
    ].join('\n');
    break;
  }

  case 'seuil':
    t = `🔔 Seuil d'alerte réglé à <b>${r0?.alert_threshold}</b>/100.`;
    break;

  case 'reanalyser':
    t = `🔄 ${r0?.n ?? 0} offre(s) seront réanalysées avec ton profil actuel dans les 30 prochaines minutes.`;
    break;

  default:
    t = '✅ Fait.';
}

return [{ json: { ...out, text: fit(t) } }];

const ctx = $('Routeur').first().json;
const c = $json;
const p = c.profile || {};
const list = (a) => (Array.isArray(a) && a.length ? a.join(', ') : 'non précisé');
const profile = `Profil : ${p.full_name || ''} · ${p.headline || ''}\nPostes visés : ${list(p.target_roles)}\nCompétences : ${list(p.skills)}\nExpérience : ${p.years_experience ?? '?'} ans\nCV :\n${(p.cv_text || 'non fourni').slice(0, 5000)}`;

if (ctx.ai === 'prep') {
  if (!c.job) return [{ json: { chat_id: ctx.chat_id, skip: true, text: `🤷 Offre #${ctx.job_id} introuvable. Vérifie avec /offres.` } }];
  const j = c.job;
  return [{ json: {
    chat_id: ctx.chat_id, ai: 'prep', job_id: j.id, job_title: j.title, company: j.company,
    llm_body: {
      temperature: 0.5,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: "Tu es un recruteur tech et coach d'entretien. Prépare le candidat à un entretien pour l'offre donnée, en t'appuyant sur son profil.\nRéponds UNIQUEMENT avec un objet JSON valide en français :\n{\n  \"pitch\": \"Pitch de présentation de 45 secondes à la 1re personne, adapté au poste\",\n  \"questions\": [{\"q\": \"Question probable\", \"tip\": \"Comment y répondre avec SES expériences (1-2 phrases)\"}],\n  \"technical\": [\"Sujets techniques à réviser en priorité\"],\n  \"ask_them\": [\"Questions pertinentes à poser au recruteur\"],\n  \"traps\": [\"Pièges à éviter\"]\n}\nDonne 6 questions (mélange motivation, comportemental et technique), 4 sujets techniques, 3 questions à poser, 3 pièges." },
        { role: 'user', content: `${profile}\n\nOFFRE #${j.id} : ${j.title} chez ${j.company || '?'} (${j.location || ''}, ${j.contract_type || ''})\nCompétences clés : ${list(j.key_skills)}\nPoints forts : ${list(j.strengths)}\nÉcarts : ${list(j.gaps)}\nDescription :\n${(j.description || '').slice(0, 5000)}` },
      ],
    },
  } }];
}

// Coach : question libre
return [{ json: {
  chat_id: ctx.chat_id, ai: 'coach',
  llm_body: {
    temperature: 0.7,
    messages: [
      { role: 'system', content: "Tu es « Job Hunter IA », coach carrière tech francophone intégré à un bot Telegram.\nTu réponds aux questions du candidat sur sa recherche d'emploi, en t'appuyant sur son profil, son pipeline de candidatures et les offres récentes fournies en contexte.\nStyle : chaleureux, concret, actionnable, 150 mots maximum, texte brut (pas de Markdown, pas d'astérisques), quelques emojis sobres.\nQuand c'est pertinent, cite les offres par leur commande, par exemple /offre_12." },
      { role: 'user', content: `${profile}\n\nPipeline (nombre d'offres par statut) : ${JSON.stringify(c.pipeline)}\nCompétences manquantes fréquentes : ${list(c.missing_skills)}\nOffres récentes : ${JSON.stringify(c.recent_jobs)}\n\nQUESTION : ${ctx.question}` },
    ],
  },
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};
// Telegram limite un message à 4096 caractères : on coupe proprement à la fin d'une ligne
const fit = (text, max = 3900) => {
  if (text.length <= max) return text;
  const cut = text.lastIndexOf('\n', max);
  return text.slice(0, cut > 0 ? cut : max) + '\n…';
};

const req = $('Préparer la demande IA').first().json;
const out = { chat_id: req.chat_id, job_id: req.job_id ?? null, kind: null, content: null };

if (req.ai === 'coach') {
  const answer = $json.choices?.[0]?.message?.content?.trim();
  return [{ json: { ...out, text: fit(answer ? esc(answer) : `⚠️ Le coach IA est indisponible pour le moment (${esc($json.error?.message || 'réponse vide')}).`) } }];
}

let r;
try { r = parseLLM($json); } catch (e) {
  return [{ json: { ...out, text: `⚠️ Préparation d'entretien impossible (${esc(e.message)}). Réessaie avec /entretien_${req.job_id}.` } }];
}
const lines = [
  `🎤 <b>Préparation d'entretien</b>`,
  `<b>${esc(req.job_title)}</b>${req.company ? ' · ' + esc(req.company) : ''}`,
  '', '🗣️ <b>Ton pitch (45 s)</b>', esc(r.pitch || ''),
  '', '❓ <b>Questions probables</b>',
  ...(r.questions || []).slice(0, 6).map((q, i) => `${i + 1}. <b>${esc(q.q)}</b>\n   💡 ${esc(q.tip)}`),
  '', '🛠️ <b>À réviser</b>', ...(r.technical || []).map((x) => `• ${esc(x)}`),
  '', '🙋 <b>Questions à leur poser</b>', ...(r.ask_them || []).map((x) => `• ${esc(x)}`),
  '', '🚫 <b>Pièges à éviter</b>', ...(r.traps || []).map((x) => `• ${esc(x)}`),
];
const text = fit(lines.join('\n'));
return [{ json: { ...out, text, kind: 'interview_prep', content: text.replace(/<[^>]+>/g, '') } }];

