const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// Nettoie le HTML ; si la page contient des données structurées schema.org/JobPosting, on les exploite
const ctx = $('Routeur').first().json;
if (ctx.pasted) {
  // Offre copiée-collée directement dans Telegram
  return [{ json: {
    chat_id: ctx.chat_id,
    url: null,
    llm_body: {
      temperature: 0,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: "Tu extrais les informations d'une offre d'emploi à partir du contenu d'une page web.\nRéponds UNIQUEMENT avec un objet JSON valide :\n{\n  \"is_job_offer\": true,\n  \"title\": \"Intitulé du poste\",\n  \"company\": \"Entreprise ou null\",\n  \"location\": \"Ville / pays / Remote ou null\",\n  \"contract_type\": \"CDI, CDD, Freelance, Stage, Alternance... ou null\",\n  \"salary\": \"Salaire indiqué ou null\",\n  \"published_at\": \"Date ISO 8601 si présente, sinon null\",\n  \"description\": \"Description complète et fidèle du poste (missions, profil, stack, avantages), 4000 caractères max\"\n}\nSi la page n'est pas une offre d'emploi, renvoie {\"is_job_offer\": false}." },
        { role: 'user', content: `TEXTE DE L'OFFRE (copié-collé) :\n${ctx.pasted}` },
      ],
    },
  } }];
}
const html = typeof $json.html === 'string' ? $json.html : '';
if (!html || $json.error) {
  return [{ json: { chat_id: ctx.chat_id, skip: true, text: `⚠️ Je n'ai pas pu ouvrir cette page (${esc($json.error?.message || 'page vide')}). Certains sites bloquent les robots : copie-colle plutôt le texte de l'offre ici.` } }];
}

let jsonLd = '';
for (const m of html.matchAll(/<script[^>]*application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
  if (/JobPosting/i.test(m[1])) { jsonLd = m[1].trim().slice(0, 8000); break; }
}
const decode = (s) => s.replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;|&apos;/g, "'").replace(/&quot;/g, '"');
const text = decode(html
  .replace(/<(script|style|noscript|svg|nav|footer|header)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/(p|div|li|h\d)>/gi, '\n')
  .replace(/<[^>]+>/g, ' '))
  .replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim().slice(0, 12000);

if (!jsonLd && text.length < 200) {
  return [{ json: { chat_id: ctx.chat_id, skip: true, text: '⚠️ La page semble vide (site chargé en JavaScript ?). Copie-colle le texte de l\'offre ici et je l\'analyserai.' } }];
}

return [{ json: {
  chat_id: ctx.chat_id,
  url: ctx.url,
  llm_body: {
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: "Tu extrais les informations d'une offre d'emploi à partir du contenu d'une page web.\nRéponds UNIQUEMENT avec un objet JSON valide :\n{\n  \"is_job_offer\": true,\n  \"title\": \"Intitulé du poste\",\n  \"company\": \"Entreprise ou null\",\n  \"location\": \"Ville / pays / Remote ou null\",\n  \"contract_type\": \"CDI, CDD, Freelance, Stage, Alternance... ou null\",\n  \"salary\": \"Salaire indiqué ou null\",\n  \"published_at\": \"Date ISO 8601 si présente, sinon null\",\n  \"description\": \"Description complète et fidèle du poste (missions, profil, stack, avantages), 4000 caractères max\"\n}\nSi la page n'est pas une offre d'emploi, renvoie {\"is_job_offer\": false}." },
      { role: 'user', content: `URL : ${ctx.url}\n\n${jsonLd ? 'DONNÉES STRUCTURÉES (JSON-LD) :\n' + jsonLd + '\n\n' : ''}TEXTE DE LA PAGE :\n${text}` },
    ],
  },
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};

const req = $('Extraire le contenu').first().json;
let r;
try { r = parseLLM($json); } catch (e) {
  return [{ json: { chat_id: req.chat_id, ok: false, text: `⚠️ Extraction impossible (${esc(e.message)}).` } }];
}
if (!r.is_job_offer || !r.title) {
  return [{ json: { chat_id: req.chat_id, ok: false, text: '🤔 Cette page ne ressemble pas à une offre d\'emploi.' } }];
}
const date = r.published_at && !Number.isNaN(Date.parse(r.published_at)) ? new Date(r.published_at).toISOString() : null;
// Une offre collée n'a pas d'URL : on l'identifie par une empreinte de son contenu
const fingerprint = 'texte:' + [...`${r.title}|${r.company}|${(r.description || '').slice(0, 300)}`].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7).toString(36);
return [{ json: { chat_id: req.chat_id, ok: true, job: {
  source: 'manuel', external_id: req.url || fingerprint, url: req.url,
  title: String(r.title).slice(0, 300), company: r.company || null, location: r.location || null,
  contract_type: r.contract_type || null, salary: r.salary || null,
  description: String(r.description || '').slice(0, 8000), published_at: date,
} } }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const j = $json;
return [{ json: {
  chat_id: $('Routeur').first().json.chat_id,
  job_id: j.id,
  text: `📥 <b>Offre ${j.created ? 'importée' : 'mise à jour'}</b> (#${j.id})\n${esc(j.title)}${j.company ? ' · ' + esc(j.company) : ''}\n\n🤖 Analyse IA en cours, je t'envoie le résultat dans quelques secondes…`,
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const ctx = $('Routeur').first().json;
const text = String($json.text || '').replace(/\s+\n/g, '\n').trim();
if ($json.error || text.length < 100) {
  return [{ json: { chat_id: ctx.chat_id, skip: true, text: '⚠️ Je n\'arrive pas à lire ce PDF (scan ou image ?). Essaie avec un PDF exporté depuis Word / Google Docs.' } }];
}
return [{ json: {
  chat_id: ctx.chat_id,
  cv_text: text.slice(0, 15000),
  llm_body: {
    temperature: 0,
    response_format: { type: 'json_object' },
    messages: [
      { role: 'system', content: "Tu analyses un CV et en extrais un profil structuré pour un outil de recherche d'emploi.\nRéponds UNIQUEMENT avec un objet JSON valide en français :\n{\n  \"full_name\": \"Prénom Nom\",\n  \"headline\": \"Titre professionnel court (ex. Développeur full-stack junior)\",\n  \"target_roles\": [\"3 à 5 intitulés de postes adaptés au profil\"],\n  \"skills\": [\"Compétences techniques et outils, noms courts (20 max)\"],\n  \"languages\": [\"Langues parlées avec niveau si présent\"],\n  \"years_experience\": 0,\n  \"locations\": [\"Ville(s) mentionnée(s) dans le CV\"],\n  \"strengths\": [\"3 atouts majeurs du profil\"]\n}" },
      { role: 'user', content: text.slice(0, 12000) },
    ],
  },
} }];

const parseLLM = (resp) => {
  if (resp?.error) throw new Error(resp.error.message || JSON.stringify(resp.error).slice(0, 300));
  const content = resp?.choices?.[0]?.message?.content;
  if (!content) throw new Error('Réponse vide du modèle IA');
  const clean = content.trim().replace(/^```(?:json)?\s*/i, '').replace(/```$/, '').trim();
  return JSON.parse(clean);
};

const req = $('Préparer l\'analyse du CV').first().json;
let r = {};
try { r = parseLLM($json); } catch (e) { r = {}; }
const arr = (a, n) => (Array.isArray(a) ? a.filter((x) => typeof x === 'string' && x.trim()).map((x) => x.trim().slice(0, 80)).slice(0, n) : []);
const years = Number.isFinite(Number(r.years_experience)) ? Math.max(0, Math.min(50, Math.round(Number(r.years_experience)))) : null;
return [{ json: {
  profile: {
    full_name: r.full_name || null,
    headline: r.headline || null,
    cv_text: req.cv_text,
    target_roles: arr(r.target_roles, 6),
    skills: arr(r.skills, 25),
    languages: arr(r.languages, 6),
    locations: arr(r.locations, 5),
    years_experience: years,
  },
  strengths: arr(r.strengths, 3),
} }];

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const p = $json;
const strengths = $('Valider le profil').first().json.strengths;
return [{ json: {
  chat_id: $('Routeur').first().json.chat_id,
  text: [
    '✅ <b>Profil mis à jour à partir de ton CV</b>',
    '',
    `👤 ${esc(p.full_name || '—')} · ${esc(p.headline || '')}`,
    `🎯 Postes : ${esc((p.target_roles || []).join(', '))}`,
    `🛠️ ${(p.skills || []).length} compétences détectées : ${esc((p.skills || []).slice(0, 12).join(', '))}${(p.skills || []).length > 12 ? '…' : ''}`,
    `⏳ Expérience : ${p.years_experience ?? '—'} an(s)`,
    ...(strengths.length ? ['', '💪 <b>Tes atouts</b>', ...strengths.map((s) => `• ${esc(s)}`)] : []),
    '', '👉 Tape /reanalyser pour recalculer les scores des offres récentes avec ce profil.',
  ].join('\n'),
} }];
